    if observation["action"] == "cooperate":
        new_reputation = current_reputation + 0.7
    else:
        new_reputation = current_reputation - 0.7
    # Apply slight decay to adapt to changing behavior
    new_reputation = new_reputation * 0.98
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Start cooperative on first round to build trust
    if round_num == 1:
        return True
    # Dynamic threshold: more lenient early, stricter later
    threshold = -0.3 if round_num < 20 else 0.2
    # Also check if recipient has ever cooperated before
    has_cooperated_before = any(
        h['recipient_reputation'] >= -0.5 and h['action'] == 'cooperate' 
        for h in my_history
    )
    return recipient_reputation >= threshold or has_cooperated_before

